import type {ReactNode} from 'react'
import {CatalogPanel} from './catalog-panel'
export function SubmissionDetails({items,message,messageLabel='Message'}:{items:{label:string;value:ReactNode}[];message:string;messageLabel?:string}){return <CatalogPanel title="Submission details" description="Contact information and submission context."><div className="application-details-body"><dl className="application-details">{items.map(item=><div key={item.label}><dt>{item.label}</dt><dd>{item.value||'Not specified'}</dd></div>)}</dl><section className="application-letter-section"><span>{messageLabel}</span><p className={`application-letter${message?'':' is-empty'}`}>{message||'No message provided.'}</p></section></div></CatalogPanel>}
export function SubmissionReplyHistory({replies}:{replies:{id:number;subject:string;body:string;status:string;created_at:string}[]}){return <CatalogPanel title="Reply history" bodyClassName="application-replies">{replies.map(reply=><article className="application-reply" key={reply.id}><header className="application-reply-header"><strong>{reply.subject}</strong><div className="application-reply-meta"><span className="application-reply-status" data-status={reply.status}>{reply.status[0].toUpperCase()+reply.status.slice(1)}</span><time dateTime={new Date(reply.created_at).toISOString()}>{new Date(reply.created_at).toLocaleString('en-GB')}</time></div></header><div className="application-reply-message"><p>{reply.body}</p></div></article>)}{!replies.length&&<p className="application-replies-empty">No replies yet.</p>}</CatalogPanel>}
